import{_ as e,o as r,c,a5 as t}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"C# CPU 与性能诊断：高 CPU、慢响应与启动慢","description":"本页回答三个问题：CPU 高时如何定位热点，响应慢如何区分 CPU、I/O 和锁竞争，如何用工具量化性能。编译与运行机制见JIT 与 AOT。","frontmatter":{"type":"explanation","level":"advanced"},"headers":[],"relativePath":"csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md","filePath":"csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"}'),s={name:"csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"};function p(i,a,n,o,d,l){return r(),c("div",null,[...a[0]||(a[0]=[t('<h1 id="c-cpu-与性能诊断-高-cpu、慢响应与启动慢" tabindex="-1" data-src-line="2" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">C# CPU 与性能诊断：高 CPU、慢响应与启动慢 <a class="header-anchor" href="#c-cpu-与性能诊断-高-cpu、慢响应与启动慢" aria-label="Permalink to &quot;C# CPU 与性能诊断：高 CPU、慢响应与启动慢&quot;">​</a></h1><p data-src-line="4" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">本页回答三个问题：CPU 高时如何定位热点，响应慢如何区分 CPU、I/O 和锁竞争，如何用工具量化性能。编译与运行机制见<a href="./../../02-dotnet-runtime/chapter-04-jit-aot.html">JIT 与 AOT</a>。</p><h2 id="_1-先量化现象" tabindex="-1" data-src-line="6" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">1. 先量化现象 <a class="header-anchor" href="#_1-先量化现象" aria-label="Permalink to &quot;1. 先量化现象&quot;">​</a></h2><p data-src-line="8" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">「慢」是主观感受，先量化：</p><ul data-src-line="10" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><li data-src-line="10" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">CPU 利用率（<code>dotnet-counters</code> 的 <code>cpu-usage</code>）。</li><li data-src-line="11" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">请求耗时（APM、日志、<code>Stopwatch</code>）。</li><li data-src-line="12" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">吞吐量（单位时间处理的请求数）。</li></ul><p data-src-line="14" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">先确定是「CPU 高」还是「响应慢但 CPU 不高」。CPU 高通常是计算热点或 GC；CPU 不高但响应慢通常是 I/O 等待或锁竞争。二者定位方向完全不同。</p><h2 id="_2-定位-cpu-热点" tabindex="-1" data-src-line="16" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">2. 定位 CPU 热点 <a class="header-anchor" href="#_2-定位-cpu-热点" aria-label="Permalink to &quot;2. 定位 CPU 热点&quot;">​</a></h2><p data-src-line="18" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">CPU 高时用 <code>dotnet-trace</code> 采集 CPU 采样：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotnet-trace collect --process-id &lt;pid&gt; --providers Microsoft-DotNETCore-SampleProfiler</span></span></code></pre></div><p data-src-line="24" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">采样结果给出每个方法占用 CPU 的比例，按占比排序找到热点方法。热点可能是：</p><ul data-src-line="26" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><li data-src-line="26" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">业务计算循环（排序、序列化、加密）。</li><li data-src-line="27" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">GC（<code>% Time in GC</code> 高，见<a href="./../01-memory/chapter-01-memory-diagnostics.html">内存诊断</a>）。</li><li data-src-line="28" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">过度日志或字符串拼接。</li></ul><p data-src-line="30" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">找到热点后，针对具体方法优化：降低复杂度、减少分配、用更高效的数据结构。优化后再采样验证 CPU 占比下降。</p><h2 id="_3-区分-i-o-等待与锁竞争" tabindex="-1" data-src-line="32" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">3. 区分 I/O 等待与锁竞争 <a class="header-anchor" href="#_3-区分-i-o-等待与锁竞争" aria-label="Permalink to &quot;3. 区分 I/O 等待与锁竞争&quot;">​</a></h2><p data-src-line="34" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">CPU 不高但响应慢，通常是线程在等 I/O 或锁：</p><ul data-src-line="36" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><li data-src-line="36" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><strong>I/O 等待</strong>：请求耗时花在数据库、外部 API、磁盘。用链路追踪（APM）或日志定位是哪个下游慢。</li><li data-src-line="37" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><strong>锁竞争</strong>：大量线程等同一把锁（见<a href="./../02-concurrency/chapter-01-concurrency-diagnostics.html">并发诊断</a>）。</li></ul><p data-src-line="39" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">用 <code>dotnet-trace</code> 或转储看线程等待原因，区分「等 I/O」和「等锁」。</p><h2 id="_4-启动慢" tabindex="-1" data-src-line="41" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">4. 启动慢 <a class="header-anchor" href="#_4-启动慢" aria-label="Permalink to &quot;4. 启动慢&quot;">​</a></h2><p data-src-line="43" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">启动慢单独一类问题。根因可能是：</p><ul data-src-line="45" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><li data-src-line="45" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">JIT 编译开销：冷启动时大量方法首次编译（见<a href="./../../02-dotnet-runtime/chapter-04-jit-aot.html">JIT 与 AOT</a>）。</li><li data-src-line="46" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">依赖注入容器注册过多、启动时做重活。</li><li data-src-line="47" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">静态初始化、配置加载。</li></ul><p data-src-line="49" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">启动敏感的 CLI 工具可评估 ReadyToRun 或 NativeAOT（见<a href="./../../02-dotnet-runtime/chapter-04-jit-aot.html">JIT 与 AOT</a>）。服务端启动慢更多是启动流程里塞了不该做的事。</p><h2 id="_5-性能诊断原则" tabindex="-1" data-src-line="51" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">5. 性能诊断原则 <a class="header-anchor" href="#_5-性能诊断原则" aria-label="Permalink to &quot;5. 性能诊断原则&quot;">​</a></h2><ol data-src-line="53" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><li data-src-line="53" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><strong>先测量</strong>：用 <code>dotnet-counters</code>、<code>dotnet-trace</code> 量化，不凭感觉。</li><li data-src-line="54" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><strong>找热点</strong>：用采样定位最耗时的少数方法，而不是漫无目的地优化。</li><li data-src-line="55" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><strong>对症优化</strong>：CPU 热点、I/O 等待、锁竞争、启动慢的优化手段不同。</li><li data-src-line="56" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><strong>量化验证</strong>：优化前后对比指标，确认是真实改进，避免「优化」引入新问题。</li></ol><p data-src-line="58" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">性能优化的最大浪费是优化了不慢的地方。用数据驱动，先优化真实热点。</p><h2 id="_6-后续阅读" tabindex="-1" data-src-line="60" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">6. 后续阅读 <a class="header-anchor" href="#_6-后续阅读" aria-label="Permalink to &quot;6. 后续阅读&quot;">​</a></h2><ul data-src-line="62" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><li data-src-line="62" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><a href="./../../02-dotnet-runtime/chapter-04-jit-aot.html">JIT 与 AOT</a>解释编译模式与启动。</li><li data-src-line="63" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><a href="./../../02-dotnet-runtime/chapter-03-gc.html">GC</a>解释 GC 对 CPU 的影响。</li><li data-src-line="64" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><a href="./../01-memory/chapter-01-memory-diagnostics.html">内存诊断</a>解释 GC 高与内存问题。</li><li data-src-line="65" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><a href="./../02-concurrency/chapter-01-concurrency-diagnostics.html">并发诊断</a>解释锁竞争。</li><li data-src-line="66" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><a href="./chapter-02-cpu-hotspot-case.html">CPU 热点案例</a>看一次 LINQ 多次枚举的完整排查。</li></ul><blockquote data-src-line="68" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md"><p data-src-line="68" data-src-file="csharp/07-diagnostics/03-performance/chapter-01-cpu-performance.md">本页的技术边界按 .NET 10 / C# 14 核对；<code>dotnet-trace</code>、<code>dotnet-counters</code> 随 .NET SDK 提供。官方参考：<a href="https://learn.microsoft.com/en-us/dotnet/core/diagnostics/" target="_blank" rel="noreferrer">.NET 诊断</a>、<a href="https://learn.microsoft.com/en-us/dotnet/core/diagnostics/dotnet-trace" target="_blank" rel="noreferrer">分析 CPU 使用</a>。</p></blockquote>',26)])])}const f=e(s,[["render",p]]);export{h as __pageData,f as default};
